using MediatR;using OAS.Application.Abstractions.Numbering;using OAS.Application.Abstractions.Persistence;using OAS.Application.Abstractions.Persistence.Specifications;using OAS.Contracts.Sales.Common;using OAS.Domain.Sales;using OAS.Domain.Sales.Entities;
namespace OAS.Application.Sales.SalesInvoices.Commands;
public sealed class ReserveSalesInvoiceCodeCommandHandler(ISequenceNumberGenerator sequences,IReadRepository<SalesInvoice,Guid> repository):IRequestHandler<ReserveSalesInvoiceCodeCommand,SalesCodeReservationDto>{public async Task<SalesCodeReservationDto> Handle(ReserveSalesInvoiceCodeCommand r,CancellationToken ct){for(var i=0;i<100;i++){var code=SalesInvoiceCodeFormatter.Format(await sequences.NextAsync("SalesInvoiceCodeSequence",ct),r.InvoiceDate);if(await repository.CountAsync(new Specification<SalesInvoice>().Where(x=>x.InvoiceCode==code),ct)==0)return new(code);}throw new InvalidOperationException("Unable to reserve a unique sales invoice code.");}}
